382	/// A dynamic representation of attribute backed by a native type implementing
383	/// - the standard `Reflect` and `FromValue` traits for casting from a value,
384	/// - the special `IntoAttr` trait for conversion into an attribute string.
385	#[derive(Copy, Clone)]
386	struct NativeType {
387	    input: fn() -> CastInfo,
388	    cast: fn(Value) -> HintedStrResult<Option<EcoString>>,
389	    castable: fn(&Value) -> bool,
390	}
391	
392	impl NativeType {
393	    /// Creates a dynamic native type from a native Rust type.
394	    const fn of<T: IntoAttr>() -> Self {
395	        Self {
396	            cast: |value| {
397	                let this = value.cast::<T>()?;
398	                Ok(Some(this.into_attr()))
399	            },
400	            input: T::input,
401	            castable: T::castable,
402	        }
403	    }
404	}
