593	        let fmt = typst_utils::display(|f| match self {
594	            Self::Date(date) => datetime::date(f, date),
595	            Self::Time(time) => datetime::time(f, time),
596	            Self::Datetime(datetime) => datetime::datetime(f, datetime),
597	        });
598	        eco_format!("{fmt}")
599	    }
