671	/// <https://html.spec.whatwg.org/#image-candidate-string>
672	pub struct ImageCandidate(EcoString);
673	
674	cast! {
675	    ImageCandidate,
676	    mut v: Dict => {
677	        let src = v.take("src")?.cast::<EcoString>()?;
678	        let width: Option<NonZeroU64> =
679	            v.take("width").ok().map(Value::cast).transpose()?;
680	        let density: Option<PositiveF64> =
681	            v.take("density").ok().map(Value::cast).transpose()?;
682	        v.finish(&["src", "width", "density"])?;
683	
684	        if src.is_empty() {
685	            bail!("`src` must not be empty");
686	        } else if src.starts_with(',') || src.ends_with(',') {
687	            bail!("`src` must not start or end with a comma");
688	        }
689	
690	        let mut out = src;
691	        match (width, density) {
